async function approveAction(id) { const a = findAction(id); if (!a) { alert('Action not found. Refresh and retry.'); return; } const s = a.scope; if (!confirm(`Approve ${a.type} ${id.slice(0, 8)} for 60 minutes?\nScope: ${s.payload_summary}\nChannel: ${s.channel || 'none'} · Recipient: ${s.recipient || 'none'}\nMax cost: ${s.max_cost_aud} · Real execution: NO\nNo spend and no real execution will be permitted. Your approval is signed and bound to scope ${a.scope_hash.slice(0, 12)}.`)) return; await humanOp('approve', id, { expires_at: new Date(Date.now() + 3600000).toISOString(), spend_cap_aud: 0, real_execution_permitted: false }); }
