function attentionBlock() { const items = runs().filter(run => ['FAILED', 'BLOCKED', 'REJECTED'].includes(run.status) || run.errors?.length || (run.receipt && !run.receipt.sealed)); return `<section class="panel attention-panel"><div class="attention-heading"><div><span class="eyebrow">WHAT NEEDS MY ATTENTION</span><h2>${items.length ? `${items.length} item${items.length === 1 ? '' : 's'} require review` : 'All systems clear'}</h2></div><span class="panel-meta">PERSISTED CONDITIONS</span></div>${items.length ? items.slice(0, 6).map(run => `<button class="attention-item" data-run-id="${esc(run.run_id)}"><span class="attention-mark">!</span><span><strong>${esc(run.objective || 'Untitled run')}</strong><small>${esc(run.status)}${run.errors?.length ? ` · ${run.errors.length} errors` : ''}</small></span><span>↗</span></button>`).join('') : '<p class="muted-copy">No failed, blocked, rejected, or unsealed run records are currently reported.</p>'}</section>`; }
function cycleBlock() { const cycle = state.cycles[0]; if (!cycle) return `<section class="panel cycle-panel"><div class="attention-heading"><div><span class="eyebrow">AUTONOMOUS ENGINE / CIVILIZATION LOOP</span><h2>No autonomous cycle has been executed.</h2></div><button class="primary-button" data-run-cycle="dry">Run dry observation</button></div><p class="muted-copy">The engine can observe, analyze, and propose without acquiring execution authority.</p></section>`; return `<section class="panel cycle-panel"><div class="attention-heading"><div><span class="eyebrow">AUTONOMOUS ENGINE / CIVILIZATION LOOP</span><h2>Cycle ${esc(cycle.cycle_id.slice(0, 8))} · ${esc(cycle.status)}</h2></div><button class="primary-button" data-run-cycle="dry">Run another dry cycle</button></div><div class="cycle-grid"><div><span class="eyebrow">OBSERVATION</span><strong>${cycle.observation.settlement.population} people · generation ${cycle.observation.settlement.generation}</strong></div><div><span class="eyebrow">FINDINGS</span><strong>${cycle.findings.length} structured finding${cycle.findings.length === 1 ? '' : 's'}</strong></div><div><span class="eyebrow">PROPOSALS</span><strong>${cycle.proposals.length} mission proposal${cycle.proposals.length === 1 ? '' : 's'}</strong></div><div><span class="eyebrow">AUTHORIZATION</span><strong>${cycle.authorization_decisions.map(item => item.status).join(', ') || 'NONE'}</strong></div></div><p class="muted-copy">No execution is implied by observation or proposal. Evidence and verification remain separate stages.</p></section>`; }
function primeCommandBlock() { return `<section class="panel prime-command-panel"><div class="prime-command-intro"><span class="eyebrow accent">YOUR SYSTEM PROMPT</span><h2>Tell Prime what outcome you need.</h2><p class="muted-copy">Ask for a supported system task or a readout. Prime routes requests to bounded workflows and asks when intent is unclear. Try one of the examples to see what is available today.</p></div><form id="prime-command-form" class="prime-command-form"><label class="visually-hidden" for="prime-command-input">Message Prime</label><textarea id="prime-command-input" name="command" rows="3" maxlength="18000" placeholder="What should the system help you understand or get done?" autocomplete="off"></textarea><button class="primary-button" type="submit">Send to Prime <span aria-hidden="true">↗</span></button></form><div class="prompt-examples" aria-label="Example prompts"><span>TRY</span><button type="button" data-prime-example="Please inspect this project and tell me what capabilities it has.">Inventory system capabilities</button><button type="button" data-prime-example="Train the Academy for 'future government ambitions', 'AI infrastructure' and 'agent work'">Train the Academy on topics</button><button type="button" data-prime-example="Tell me what the agents are doing and summarize their latest work.">Report agent work</button><button type="button" data-prime-example="Check the Academy progress and summarize the next useful action.">Check Academy progress</button></div><div class="prompt-safety"><span aria-hidden="true">◈</span><span><strong>Clear control boundary</strong> — plans are shown before new missions start; real-world or sensitive actions may require explicit human approval.</span></div><div id="prime-command-result" class="prime-command-result" aria-live="polite"></div></section>`; }
function systemFlowBlock() { return `<section class="system-flow-panel"><div class="section-heading"><div><span class="eyebrow">THE EXECUTION PATH</span><h2>How a request becomes a result</h2></div><span class="panel-meta">FOLLOW EVERY HANDOFF</span></div><ol class="system-flow"><li><span class="flow-index">01</span><div><strong>You describe an outcome</strong><p>Ask Prime directly, in your own words.</p></div></li><li><span class="flow-index">02</span><div><strong>Prime understands &amp; routes</strong><p>It answers, clarifies intent, or prepares a mission plan.</p></div></li><li><span class="flow-index">03</span><div><strong>Bounded agents do the work</strong><p>Specialists act only within their declared authority.</p></div></li><li><span class="flow-index">04</span><div><strong>Approval gates sensitive actions</strong><p>Review the proposed scope; execution is never implied by a suggestion.</p></div></li><li><span class="flow-index">05</span><div><strong>Evidence closes the loop</strong><p>Runs, events, and receipts let you inspect what happened.</p></div></li></ol><div class="system-flow-note"><span>SIMULATION ≠ THE SYSTEM</span><p>Lake Yange is the example world the execution network operates. Its population and institutions are simulated records, not real-world business activity.</p></div></section>`; }
async function executePrimeCommand(event) {
  event.preventDefault();
  const input = $('#prime-command-input');
  const result = $('#prime-command-result');
  const button = $('#prime-command-form button');
  const message = input?.value.trim();
  if (!message || !button || !result) return;
  state.pendingPrimeMission = null;
  state.primeSubmitting = true;
  button.disabled = true;
  result.classList.remove('error');
  result.textContent = 'Prime is considering your request...';
  let response;
  let refreshAfterResponse = false;
  try {
    response = await api('/api/prime/message', {
      method: 'POST',
      headers: {'content-type': 'application/json'},
      body: JSON.stringify({message})
    });
    if (response.status === 'NEEDS_CLARIFICATION' && !response.engineering && !response.constitutional) {
      const agentResponse = await api('/api/prime/agent-command', {
        method: 'POST',
        headers: {'content-type': 'application/json'},
        body: JSON.stringify({command: message})
      });
      if (agentResponse.status !== 'UNSUPPORTED') response = agentResponse;
    }
    if (response.status === 'READY' && response.mission) {
      state.pendingPrimeMission = response.mission;
      result.innerHTML = `<strong>${esc(response.status)} · REVIEW BEFORE START</strong><span>${esc(response.reply)}</span><article class="prime-mission-preview"><span class="eyebrow">${esc(response.mission.workflow)}</span><strong>${esc(response.mission.objective)}</strong>${(response.assumptions || []).map(item => `<small>${esc(item)}</small>`).join('')}<button class="primary-button" id="prime-launch-mission" type="button">Start this mission</button></article>`;
    } else {
      const statusClass = response.status === 'COMPLETED' ? 'status-completed' : response.status === 'FAILED' ? 'status-failed' : ['UNSUPPORTED', 'NEEDS_CLARIFICATION'].includes(response.status) ? 'status-unsupported' : '';
      result.innerHTML = `<strong class="${statusClass}">${esc(response.status)}</strong><span>${esc(response.reply)}</span>`;
      refreshAfterResponse = response.status === 'COMPLETED';
    }
    if (refreshAfterResponse) {
      await refresh();
      const refreshedResult = $('#prime-command-result');
      if (refreshedResult) refreshedResult.innerHTML = `<strong class="status-completed">${esc(response.status)}</strong><span>${esc(response.reply)}</span>`;
    } else if (response.status !== 'NEEDS_CLARIFICATION' && response.status !== 'UNSUPPORTED') {
      input.value = '';
    }
  } catch (error) {
    result.textContent = error.message;
    result.classList.add('error');
  } finally {
    state.primeSubmitting = false;
    const activeButton = $('#prime-command-form button');
    if (activeButton) activeButton.disabled = false;
  }
}
async function launchPrimeMission() {
  const mission = state.pendingPrimeMission;
  const result = $('#prime-command-result');
  const button = $('#prime-launch-mission');
  if (!mission || !result || !button) return;
  button.disabled = true;
  button.textContent = 'Starting mission...';
  try {
    const started = await api('/api/prime/deploy', {
      method: 'POST',
      headers: {'content-type': 'application/json'},
      body: JSON.stringify(mission)
    });
    state.pendingPrimeMission = null;
    await refresh();
    const refreshedResult = $('#prime-command-result');
    if (refreshedResult) refreshedResult.innerHTML = `<strong class="status-completed">MISSION ACCEPTED</strong><span>${esc(started.message)} ${esc(started.workflow)} / ${esc(started.mode)}.</span>`;
  } catch (error) {
    button.disabled = false;
    button.textContent = 'Start this mission';
    result.insertAdjacentHTML('beforeend', `<span class="error-message">${esc(error.message)}</span>`);
  }
}
async function runCycle() { const button = document.querySelector('[data-run-cycle]'); if (button) button.disabled = true; try { await api('/api/lake-yange/autonomous/cycle', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ dry_run: true }) }); await refresh(); } catch (error) { if (button) button.textContent = error.message; } }
async function refresh() { try { const [projection, runList, economy, academy, cycles] = await Promise.all([api('/api/lake-yange/world'), api('/api/runs'), api('/api/lake-yange/economy'), api('/api/lake-yange/academy'), api('/api/lake-yange/autonomous/cycles')]); state.projection = projection; state.runs = runList || []; state.economy = economy; state.academy = academy; state.cycles = cycles || []; $('#footer-status').textContent = 'SYSTEM ONLINE'; $('#sidebar-runtime').textContent = 'CONNECTED'; $('#footer-agents').textContent = agents().length; $('#footer-sync').textContent = clock(new Date()); render(); } catch (error) { $('#footer-status').textContent = 'PROJECTION UNAVAILABLE'; $('#sidebar-runtime').textContent = 'OFFLINE'; $('#app').innerHTML = `<div class="page-view"><div class="error-state"><span class="empty-glyph">!</span><span class="eyebrow">SYSTEM DATA UNAVAILABLE</span><h2>Lake Yange could not load its projection.</h2><p>The persisted world state is not reachable from this console.</p><button class="primary-button" id="retry-button" type="button">Retry connection</button><details><summary>Technical details</summary><code>${esc(error.message)}</code></details></div></div>`; $('#retry-button')?.addEventListener('click', refresh); } }
function focusPrimeCommand() { if (state.view !== 'overview') navigate('overview'); $('#prime-command-input')?.focus(); }
document.querySelectorAll('.nav-item').forEach(item => item.addEventListener('click', () => navigate(item.dataset.view))); $('#open-nav').addEventListener('click', openNav); $('#close-nav').addEventListener('click', closeNav); $('#scrim').addEventListener('click', closeNav); $('#close-drawer').addEventListener('click', closeDrawer); $('#refresh-button').addEventListener('click', refresh); $('#ask-prime-trigger').addEventListener('click', focusPrimeCommand); $('#command-trigger').addEventListener('click', openPalette); $('#close-palette').addEventListener('click', closePalette); $('#command-input').addEventListener('input', event => renderCommands(event.target.value)); document.addEventListener('keydown', event => { if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); openPalette(); } if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'j') { event.preventDefault(); focusPrimeCommand(); } if (event.key === 'Escape') { closeDrawer(); closeNav(); if ($('#command-palette').open) closePalette(); } }); document.addEventListener('keydown', event => { if ((event.metaKey || event.ctrlKey) && event.key === 'Enter' && event.target.id === 'prime-command-input') { event.preventDefault(); $('#prime-command-form')?.requestSubmit(); } }); await refresh(); setInterval(refresh, 15000);
